#[cfg(test)]
mod tests {
    use super::*;

    // Test 1: AggregatedForecasting 기본 통합
    #[test]
    fn test_aggregated_forecasting_basic() {
        let af = AggregatedForecasting::new();
        let forecasts = vec![
            NodeForecast {
                node_id: 1,
                pattern_type: "MemoryLeak".to_string(),
                predicted_saturation: 0.75,
                confidence: 0.9,
                time_to_critical: 300,
                freshness_score: 95.0,
            },
            NodeForecast {
                node_id: 2,
                pattern_type: "MemoryLeak".to_string(),
                predicted_saturation: 0.78,
                confidence: 0.85,
                time_to_critical: 280,
                freshness_score: 92.0,
            },
            NodeForecast {
                node_id: 3,
                pattern_type: "MemoryLeak".to_string(),
                predicted_saturation: 0.72,
                confidence: 0.88,
                time_to_critical: 320,
                freshness_score: 90.0,
            },
        ];

        let trust_scores = HashMap::new();
        let result = af.aggregate_forecasts(&forecasts, 0, &trust_scores);

        assert!(result.consensus_saturation > 0.7 && result.consensus_saturation < 0.8);
        assert!(result.consensus_confidence > 0.85);
        assert!(result.agreement_ratio > 0.85);
        assert!(result.is_reliable);
    }

    // Test 2: AggregatedForecasting 신선도 점수
    #[test]
    fn test_freshness_score_calculation() {
        let af = AggregatedForecasting::new();

        // 최신 (0초 전)
        assert!(af.calculate_freshness_score(0) > 99.0);

        // 중간 (300초 전)
        let mid_score = af.calculate_freshness_score(300);
        assert!(mid_score > 40.0 && mid_score < 60.0);

        // 오래됨 (1000초 전)
        assert!(af.calculate_freshness_score(1000) < 10.0);
    }

    // Test 3: WeightedVoting 실행 의사결정
    #[test]
    fn test_weighted_voting_execute_decision() {
        let wv = WeightedVoting::new();
        let votes = vec![
            Vote {
                node_id: 1,
                decision: "execute".to_string(),
                confidence: 0.95,
                reasoning: "High confidence".to_string(),
            },
            Vote {
                node_id: 2,
                decision: "execute".to_string(),
                confidence: 0.9,
                reasoning: "High confidence".to_string(),
            },
            Vote {
                node_id: 3,
                decision: "prepare".to_string(),
                confidence: 0.75,
                reasoning: "Medium confidence".to_string(),
            },
        ];

        let trust_scores = HashMap::new();
        let (weighted, decision) = wv.conduct_weighted_voting(&votes, &trust_scores);

        assert_eq!(weighted.execution_votes, 2);
        assert_eq!(weighted.prepare_votes, 1);
        assert!(weighted.consensus_strength > 0.6);
        // VotingDecision은 match 패턴으로 확인
    }

    // Test 4: WeightedVoting 합의 강도
    #[test]
    fn test_weighted_voting_consensus_strength() {
        let wv = WeightedVoting::new();
        let votes = vec![
            Vote {
                node_id: 1,
                decision: "execute".to_string(),
                confidence: 0.9,
                reasoning: "".to_string(),
            },
            Vote {
                node_id: 2,
                decision: "execute".to_string(),
                confidence: 0.9,
                reasoning: "".to_string(),
            },
            Vote {
                node_id: 3,
                decision: "execute".to_string(),
                confidence: 0.9,
                reasoning: "".to_string(),
            },
            Vote {
                node_id: 4,
                decision: "prepare".to_string(),
                confidence: 0.7,
                reasoning: "".to_string(),
            },
        ];

        let trust_scores = HashMap::new();
        let (weighted, _) = wv.conduct_weighted_voting(&votes, &trust_scores);

        // 3/4 = 0.75 합의 강도
        assert!(weighted.consensus_strength > 0.7 && weighted.consensus_strength < 0.8);
    }

    // Test 5: ConflictResolution ExecuteVsPrepare 감지
    #[test]
    fn test_conflict_resolution_execute_vs_prepare() {
        let cr = ConflictResolution::new();
        let aggregated = AggregatedForecast {
            consensus_saturation: 0.75,
            consensus_confidence: 0.8,
            forecasts: vec![],
            agreement_ratio: 0.75,
            prediction_variance: 0.05,
            is_reliable: true,
        };

        let weighted = WeightedVote {
            votes: vec![],
            execution_votes: 2,
            prepare_votes: 2,
            monitor_votes: 0,
            weighted_execute_confidence: 0.88,
            weighted_prepare_confidence: 0.72,
            consensus_strength: 0.5,
        };

        let (conflict, _) = cr.detect_and_resolve_conflicts(&aggregated, &weighted, None);

        assert!(conflict.is_some());
        if let Some(c) = conflict {
            assert!(c.severity > 0.3);
        }
    }

    // Test 6: ConflictResolution 고분산 감지
    #[test]
    fn test_conflict_resolution_high_variance() {
        let cr = ConflictResolution::new();
        let aggregated = AggregatedForecast {
            consensus_saturation: 0.7,
            consensus_confidence: 0.7,
            forecasts: vec![],
            agreement_ratio: 0.4, // 낮은 일치도
            prediction_variance: 0.25, // 높은 분산
            is_reliable: false,
        };

        let weighted = WeightedVote {
            votes: vec![],
            execution_votes: 1,
            prepare_votes: 1,
            monitor_votes: 2,
            weighted_execute_confidence: 0.6,
            weighted_prepare_confidence: 0.5,
            consensus_strength: 0.5,
        };

        let (conflict, _) = cr.detect_and_resolve_conflicts(&aggregated, &weighted, None);

        assert!(conflict.is_some());
    }

    // Test 7: DistributedPredictionSystem 전체 파이프라인
    #[test]
    fn test_distributed_prediction_full_pipeline() {
        let mut dps = DistributedPredictionSystem::new();

        let forecasts = vec![
            NodeForecast {
                node_id: 1,
                pattern_type: "IOBottleneck".to_string(),
                predicted_saturation: 0.8,
                confidence: 0.92,
                time_to_critical: 250,
                freshness_score: 98.0,
            },
            NodeForecast {
                node_id: 2,
                pattern_type: "IOBottleneck".to_string(),
                predicted_saturation: 0.82,
                confidence: 0.89,
                time_to_critical: 240,
                freshness_score: 96.0,
            },
        ];

        let votes = vec![
            Vote {
                node_id: 1,
                decision: "execute".to_string(),
                confidence: 0.92,
                reasoning: "IO bottleneck critical".to_string(),
            },
            Vote {
                node_id: 2,
                decision: "execute".to_string(),
                confidence: 0.89,
                reasoning: "IO bottleneck critical".to_string(),
            },
            Vote {
                node_id: 3,
                decision: "prepare".to_string(),
                confidence: 0.75,
                reasoning: "Conservative approach".to_string(),
            },
        ];

        let trust_scores = HashMap::new();

        let (agg, weighted, conflict, decision) = dps.execute_distributed_prediction(
            &forecasts,
            &votes,
            &trust_scores,
            Some(1),
            100,
        );

        assert!(agg.consensus_saturation > 0.75);
        assert_eq!(weighted.execution_votes, 2);
        assert!(dps.decision_history.len() > 0);
    }

    // Test 8: DistributedPredictionSystem 의사결정 이력
    #[test]
    fn test_decision_history_tracking() {
        let mut dps = DistributedPredictionSystem::new();

        let forecasts = vec![NodeForecast {
            node_id: 1,
            pattern_type: "MemoryLeak".to_string(),
            predicted_saturation: 0.9,
            confidence: 0.95,
            time_to_critical: 100,
            freshness_score: 100.0,
        }];

        let votes = vec![Vote {
            node_id: 1,
            decision: "execute".to_string(),
            confidence: 0.95,
            reasoning: "Critical memory leak".to_string(),
        }];

        let trust_scores = HashMap::new();

        // 첫 번째 의사결정
        dps.execute_distributed_prediction(
            &forecasts,
            &votes,
            &trust_scores,
            None,
            100,
        );

        assert_eq!(dps.get_decision_history().len(), 1);
        assert!(dps.get_last_decision().is_some());

        // 두 번째 의사결정
        dps.execute_distributed_prediction(
            &forecasts,
            &votes,
            &trust_scores,
            None,
            200,
        );

        assert_eq!(dps.get_decision_history().len(), 2);
    }
}

