// FreeLang Phase H Week 1: Monitoring Dashboard
// 실시간 대시보드 + 히스토리 그래프 + 알람 + HTML 내보내기 (Days 5-6)

use std::collections::HashMap;

// ============================================================================
// Dashboard Core Structures
// ============================================================================

pub struct MetricSnapshot {
    metric_name: String,
    current_value: f64,
    avg_value: f64,
    p99_value: f64,
    trend: String,           // "↑" / "→" / "↓"
    last_updated_us: u64,
}

pub struct TraceMetadata {
    trace_id: String,
    operation: String,
    latency_us: u64,
    status: String,          // "completed" / "failed" / "active"
    tag_phase: Option<String>,
    tag_pattern: Option<String>,
}

pub struct AlertRule {
    metric_name: String,
    condition: String,       // "p99 > 100" / "anomaly_detected" / "slo_violation"
    severity: String,        // "critical" / "high" / "medium" / "low"
    enabled: bool,
}

pub struct Alert {
    rule_name: String,
    timestamp_us: u64,
    message: String,
    severity: String,
}

pub struct Dashboard {
    metric_snapshots: Vec<MetricSnapshot>,
    recent_traces: Vec<TraceMetadata>,
    alerts: Vec<Alert>,
    alert_rules: Vec<AlertRule>,
    slo_targets: HashMap<String, f64>,  // "p99_latency" -> 100.0
    current_time_us: u64,
}

impl Dashboard {
    pub fn new() -> Self {
        Dashboard {
            metric_snapshots: vec![],
            recent_traces: vec![],
            alerts: vec![],
            alert_rules: vec![],
            slo_targets: HashMap::new(),
            current_time_us: 0,
        }
    }

    // 실시간 메트릭 스냅샷 업데이트
    pub fn update_metric_snapshot(
        &mut self,
        metric_name: String,
        current: f64,
        avg: f64,
        p99: f64,
    ) {
        // 기존 스냅샷 찾기
        for snapshot in &mut self.metric_snapshots {
            if snapshot.metric_name == metric_name {
                let trend = if current > avg {
                    "↑".to_string()
                } else if current < avg {
                    "↓".to_string()
                } else {
                    "→".to_string()
                };

                snapshot.current_value = current;
                snapshot.avg_value = avg;
                snapshot.p99_value = p99;
                snapshot.trend = trend;
                snapshot.last_updated_us = self.current_time_us;
                return;
            }
        }

        // 새로운 스냅샷 생성
        let trend = if current > avg {
            "↑".to_string()
        } else if current < avg {
            "↓".to_string()
        } else {
            "→".to_string()
        };

        self.metric_snapshots.push(MetricSnapshot {
            metric_name,
            current_value: current,
            avg_value: avg,
            p99_value: p99,
            trend,
            last_updated_us: self.current_time_us,
        });
    }

    // 최근 트레이스 기록
    pub fn add_recent_trace(
        &mut self,
