    }

    // SLO 목표 설정
    pub fn set_slo_target(&mut self, metric_name: String, target_value: f64) {
        self.slo_targets.insert(metric_name, target_value);
    }

    // 알람 규칙 추가
    pub fn add_alert_rule(&mut self, rule: AlertRule) {
        self.alert_rules.push(rule);
    }

    // SLO 위반 확인
    pub fn check_slo_violations(&mut self) {
        for snapshot in &self.metric_snapshots {
            if let Some(&target) = self.slo_targets.get(&snapshot.metric_name) {
                if snapshot.p99_value > target {
                    self.alerts.push(Alert {
                        rule_name: format!("SLO_VIOLATION_{}", snapshot.metric_name),
                        timestamp_us: self.current_time_us,
                        message: format!(
                            "{} P99={} exceeds SLO target={}",
                            snapshot.metric_name, snapshot.p99_value, target
                        ),
                        severity: "high".to_string(),
                    });
                }
            }
        }

        // 최대 500개 알람 유지
        if self.alerts.len() > 500 {
