            self.alerts.drain(0..remove_count);
        }
    }

    // 최근 알람 조회
    pub fn get_recent_alerts(&self, count: usize) -> Vec<&Alert> {
        let start = if self.alerts.len() > count {
            self.alerts.len() - count
        } else {
            0
        };
        self.alerts[start..].iter().collect()
    }

    // 메트릭별 평균 계산
    pub fn get_metric_average(&self, metric_name: &str) -> Option<f64> {
        for snapshot in &self.metric_snapshots {
            if snapshot.metric_name == metric_name {
                return Some(snapshot.avg_value);
            }
        }
        None
    }

