        html.push_str("    .panel h2 { margin: 0 0 15px 0; font-size: 16px; color: #333; }\n");
        html.push_str("    .metric-row { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #eee; }\n");
