        html.push_str("    .trend { margin-left: 5px; font-size: 14px; }\n");
        html.push_str("    .alert-critical { color: #dc3545; }\n");
        html.push_str("    .alert-high { color: #fd7e14; }\n");
        html.push_str("    .alert-medium { color: #ffc107; }\n");
        html.push_str("    .alert-low { color: #28a745; }\n");
        html.push_str("    .trace-id { font-family: monospace; font-size: 11px; color: #666; }\n");
        html.push_str("    .status-completed { color: #28a745; }\n");
        html.push_str("    .status-failed { color: #dc3545; }\n");
        html.push_str("    .status-active { color: #0066cc; }\n");
        html.push_str("    table { width: 100%; border-collapse: collapse; }\n");
        html.push_str("    th { background: #f9f9f9; padding: 8px; text-align: left; font-weight: bold; border-bottom: 2px solid #ddd; }\n");
        html.push_str("    td { padding: 8px; border-bottom: 1px solid #eee; }\n");
        html.push_str("    tr:hover { background: #f9f9f9; }\n");
        html.push_str("  </style>\n");
        html.push_str("</head>\n");
        html.push_str("<body>\n");

        // Header
        html.push_str("  <div class=\"header\">\n");
        html.push_str("    <h1>🔍 Phase H Monitoring Dashboard</h1>\n");
        html.push_str(&format!(
            "    <div class=\"timestamp\">Timestamp: {}µs</div>\n",
            self.current_time_us
        ));
        html.push_str("  </div>\n");

        // Main Grid
        html.push_str("  <div class=\"container\">\n");
        html.push_str("    <div class=\"grid\">\n");

        // Metrics Panel
        html.push_str("      <div class=\"panel\">\n");
        html.push_str("        <h2>📊 Real-time Metrics</h2>\n");
        for snapshot in &self.metric_snapshots {
            html.push_str("        <div class=\"metric-row\">\n");
            html.push_str(&format!(
                "          <span class=\"metric-name\">{}</span>\n",
                snapshot.metric_name
            ));
            html.push_str(&format!(
                "          <span class=\"metric-value\">{:.2}{}</span>\n",
                snapshot.current_value, snapshot.trend
            ));
            html.push_str("        </div>\n");
        }
        html.push_str("      </div>\n");

        // Alerts Panel
        html.push_str("      <div class=\"panel\">\n");
        html.push_str("        <h2>⚠️ Recent Alerts</h2>\n");
        let recent_alerts = self.get_recent_alerts(5);
        if recent_alerts.is_empty() {
            html.push_str("        <div style=\"color: #28a745;\">✓ No active alerts</div>\n");
        } else {
            for alert in recent_alerts {
                html.push_str(&format!(
                    "        <div class=\"alert-{}\">⚠️ {}: {}</div>\n",
                    alert.severity.to_lowercase(),
                    alert.severity,
                    alert.message
                ));
            }
        }
        html.push_str("      </div>\n");

        html.push_str("    </div>\n");

        // Recent Traces Table
        html.push_str("    <div class=\"panel\">\n");
        html.push_str("      <h2>📈 Recent Traces</h2>\n");
        html.push_str("      <table>\n");
        html.push_str("        <thead>\n");
        html.push_str("          <tr>\n");
        html.push_str("            <th>Trace ID</th>\n");
        html.push_str("            <th>Operation</th>\n");
        html.push_str("            <th>Latency (µs)</th>\n");
        html.push_str("            <th>Status</th>\n");
        html.push_str("          </tr>\n");
        html.push_str("        </thead>\n");
        html.push_str("        <tbody>\n");

        let start = if self.recent_traces.len() > 20 {
            self.recent_traces.len() - 20
        } else {
            0
        };

        for trace in &self.recent_traces[start..] {
            let status_class = match trace.status.as_str() {
                "completed" => "status-completed",
                "failed" => "status-failed",
                "active" => "status-active",
                _ => "status-completed",
            };

            html.push_str("          <tr>\n");
            html.push_str(&format!(
                "            <td><span class=\"trace-id\">{}</span></td>\n",
                &trace.trace_id[..trace.trace_id.len().min(16)]
            ));
            html.push_str(&format!(
                "            <td>{}</td>\n",
                trace.operation
            ));
            html.push_str(&format!(
                "            <td>{}</td>\n",
                trace.latency_us
            ));
            html.push_str(&format!(
                "            <td><span class=\"{}\">{}</span></td>\n",
                status_class, trace.status
            ));
            html.push_str("          </tr>\n");
        }

        html.push_str("        </tbody>\n");
        html.push_str("      </table>\n");
        html.push_str("    </div>\n");

        html.push_str("  </div>\n");
        html.push_str("</body>\n");
        html.push_str("</html>\n");

        html
    }

    // SLO/메트릭 통계
    pub fn get_slo_compliance_report(&self) -> String {
        let mut report = String::from("=== SLO Compliance Report ===\n\n");

        for (metric_name, target) in &self.slo_targets {
            for snapshot in &self.metric_snapshots {
                if &snapshot.metric_name == metric_name {
                    let compliant = snapshot.p99_value <= *target;
                    let status = if compliant { "✓ PASS" } else { "✗ FAIL" };
                    report.push_str(&format!(
                        "{}: {} (P99={:.2} vs target={:.2})\n",
                        metric_name, status, snapshot.p99_value, target
                    ));
                }
            }
        }

        report
    }
}

