#[cfg(test)]
mod tests {
    use super::*;

    // Test 1: 대시보드 초기화
    #[test]
    fn test_dashboard_creation() {
        let dashboard = Dashboard::new();
        assert_eq!(dashboard.metric_snapshots.len(), 0);
        assert_eq!(dashboard.recent_traces.len(), 0);
        assert_eq!(dashboard.alerts.len(), 0);
    }

    // Test 2: 메트릭 스냅샷 업데이트
    #[test]
    fn test_metric_snapshot_update() {
        let mut dashboard = Dashboard::new();

        dashboard.update_metric_snapshot("cpu.utilization".to_string(), 75.0, 50.0, 95.0);
        assert_eq!(dashboard.metric_snapshots.len(), 1);
        assert_eq!(dashboard.metric_snapshots[0].current_value, 75.0);
        assert_eq!(dashboard.metric_snapshots[0].avg_value, 50.0);
        assert_eq!(dashboard.metric_snapshots[0].trend, "↑");

        // 기존 메트릭 업데이트
        dashboard.update_metric_snapshot("cpu.utilization".to_string(), 45.0, 50.0, 85.0);
        assert_eq!(dashboard.metric_snapshots.len(), 1);
        assert_eq!(dashboard.metric_snapshots[0].current_value, 45.0);
        assert_eq!(dashboard.metric_snapshots[0].trend, "↓");
    }

    // Test 3: 트레이스 추가
    #[test]
    fn test_add_recent_traces() {
        let mut dashboard = Dashboard::new();

        dashboard.add_recent_trace(
            "trace-001".to_string(),
            "api.request".to_string(),
            150,
            "completed".to_string(),
        );

        assert_eq!(dashboard.recent_traces.len(), 1);
        assert_eq!(dashboard.recent_traces[0].latency_us, 150);
    }

    // Test 4: SLO 목표 설정 및 위반 확인
    #[test]
    fn test_slo_violation_detection() {
        let mut dashboard = Dashboard::new();

        dashboard.set_slo_target("p99_latency".to_string(), 100.0);
        dashboard.update_metric_snapshot("p99_latency".to_string(), 50.0, 45.0, 120.0);

        dashboard.check_slo_violations();
        assert!(dashboard.alerts.len() > 0);
        assert!(dashboard.alerts[0].message.contains("exceeds SLO"));
    }

    // Test 5: 알람 규칙 추가
    #[test]
    fn test_alert_rule_management() {
        let mut dashboard = Dashboard::new();

        let rule = AlertRule {
            metric_name: "memory.usage_mb".to_string(),
            condition: "usage > 8000".to_string(),
            severity: "critical".to_string(),
            enabled: true,
        };

        dashboard.add_alert_rule(rule);
        assert_eq!(dashboard.alert_rules.len(), 1);
    }

    // Test 6: HTML 렌더링
    #[test]
    fn test_html_rendering() {
        let mut dashboard = Dashboard::new();

        dashboard.update_metric_snapshot("cpu.utilization".to_string(), 75.0, 50.0, 95.0);
        dashboard.add_recent_trace(
            "trace-001".to_string(),
            "api.request".to_string(),
            150,
            "completed".to_string(),
        );

        let html = dashboard.render_html();

        assert!(html.contains("<!DOCTYPE html>"));
        assert!(html.contains("Phase H Monitoring Dashboard"));
        assert!(html.contains("cpu.utilization"));
        assert!(html.contains("trace-001"));
        assert!(html.contains("</html>"));
    }

    // Test 7: SLO 준수 보고서
    #[test]
    fn test_slo_compliance_report() {
        let mut dashboard = Dashboard::new();

        dashboard.set_slo_target("p99_latency".to_string(), 100.0);
        dashboard.update_metric_snapshot("p99_latency".to_string(), 50.0, 45.0, 90.0);

        let report = dashboard.get_slo_compliance_report();

        assert!(report.contains("p99_latency"));
        assert!(report.contains("PASS"));
    }

    // Test 8: 시간 경과 및 알람 추적
    #[test]
    fn test_time_advancement_and_alerts() {
        let mut dashboard = Dashboard::new();

        dashboard.set_slo_target("p99_latency".to_string(), 100.0);
        dashboard.update_metric_snapshot("p99_latency".to_string(), 50.0, 45.0, 150.0);
        dashboard.check_slo_violations();

        assert_eq!(dashboard.alerts.len(), 1);
        assert_eq!(dashboard.current_time_us, 0);

        dashboard.advance_time(1_000_000);
        assert_eq!(dashboard.current_time_us, 1_000_000);

        // 알람은 여전히 유지
        assert_eq!(dashboard.alerts.len(), 1);
    }
}

