        metrics.insert("GC_pause_ms".to_string(), 150.0);

        let mut improvements = HashMap::new();
        improvements.insert("P99_latency_drop_percent".to_string(), 40.0);

        let (analysis, report) = stack.analyze_and_report(
            "FAIL-008".to_string(),
            "LatencyExplosion".to_string(),
            1000_000_000,
            vec![("EVT-13".to_string(), "GC".to_string(), 0.9)],
            metrics,
            vec!["GCMode(aggressive)".to_string()],
            improvements,
        );

        assert!(!report.report_markdown.is_empty());
        assert!(analysis.confidence_in_analysis > 0.0);
    }

    #[test]
    fn test_no_root_cause_identified() {
        let mut analyzer = RootCauseAnalyzer::new();
        let metrics = HashMap::new();

        let analysis = analyzer.analyze(
            "FAIL-009".to_string(),
            "UnknownClass".to_string(),
            1000_000_000,
            vec![],
            metrics,
        );

        assert!(analysis.primary_root_cause.is_none());
        assert_eq!(analysis.confidence_in_analysis, 0.0);
    }
}

