#[cfg(test)]
mod network_tests {
    use super::*;

    #[test]
    fn test_network_partition_scenario_setup() {
        // Test 1: Verify scenario initializes with correct baseline
        let scenario = NetworkPartitionScenario::new("network-001".to_string());

        assert_eq!(scenario.baseline_network_latency_us, 10_000);
        assert_eq!(scenario.baseline_throughput_mb_s, 100);
        assert_eq!(scenario.baseline_cache_coherency, 0.99);
        assert_eq!(scenario.phase, "baseline");
        assert!(!scenario.fault_injected);
    }

    #[test]
    fn test_network_partition_injection() {
        // Test 2: Verify NetworkPartition causes complete disconnect and state inconsistency
        let mut scenario = NetworkPartitionScenario::new("network-002".to_string());
        let mut injector = FaultInjector::new();

        // T-0s: Inject fault
        scenario.execute(&mut injector, 5_000);
        assert!(scenario.fault_injected);
        assert!(scenario.partition_active);

        // T+10s: Partition effects visible
        scenario.execute(&mut injector, 10_000);
        assert_eq!(scenario.current_throughput_mb_s, 0);  // Zero throughput
        assert!(scenario.current_network_latency_us > 50_000_000);  // Very high latency
        assert!(scenario.current_cache_coherency < 0.6);  // Degraded coherency
        assert!(scenario.failed_requests > 0);
    }

    #[test]
    fn test_network_partition_recovery() {
        // Test 3: Verify partition detection, policy, and full recovery
        let mut scenario = NetworkPartitionScenario::new("network-003".to_string());
        let mut injector = FaultInjector::new();

        // T-0s: Inject fault
        scenario.execute(&mut injector, 5_000);

        // T+10s: Detect violation
        scenario.execute(&mut injector, 10_000);
        assert!(scenario.slo_violations_detected > 0);
        assert!(scenario.state_inconsistency_detected);

        // T+20s: Policy applied
        scenario.execute(&mut injector, 20_000);
        assert!(!scenario.policies_applied.is_empty());
        assert_eq!(scenario.policies_applied[0], "enable_circuit_breaker");

        // T+30s: Healing begins
        scenario.execute(&mut injector, 30_000);
        assert!(scenario.healing_started);

        // T+60s: Recovery progresses
        scenario.execute(&mut injector, 60_000);
        assert!(scenario.current_throughput_mb_s > 0);  // Throughput recovering

        // T+100s: Full recovery
        scenario.execute(&mut injector, 100_000);
        assert!(scenario.recovery_successful);
        assert_eq!(scenario.current_throughput_mb_s, scenario.baseline_throughput_mb_s);
        assert_eq!(scenario.current_network_latency_us, scenario.baseline_network_latency_us);

        // Verify all success criteria
        assert!(scenario.verify());
    }
}

