        let mut report = String::new();
        report.push_str("╔═════════════════════════════════════════════════════════════╗\n");
        report.push_str("║         CHAOS ENGINEERING VALIDATION REPORT                 ║\n");
        report.push_str("║         Phase I Week 3: Days 15-17                          ║\n");
        report.push_str("╚═════════════════════════════════════════════════════════════╝\n\n");

        report.push_str(&format!("Total Scenarios: {}\n", self.total_scenarios));
        report.push_str(&format!("Passed: {}\n", self.passed_scenarios));
        report.push_str(&format!("Overall Pass Rate: {:.1}%\n\n", self.get_overall_pass_rate()));

        report.push_str("Scenario Results:\n");
        report.push_str("─────────────────────────────────────────────────────────────\n\n");

        for (_, criteria) in &self.results {
            report.push_str(&criteria.get_report());
            report.push_str("\n");
        }

        report
    }
}

// ============================================================================
// INTEGRATION TESTS
// ============================================================================

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_scenario1_tail_latency_validation() {
        let scenario = TailLatencyScenario::new("test-001".to_string());
        let criteria = TailLatencyValidator::validate(&scenario);

        // Should have 5 criteria
        assert_eq!(criteria.criteria.len(), 5);

        // Verify generates proper report
        let report = criteria.get_report();
        assert!(report.contains("Scenario 1: Tail Latency Under Load"));
    }

    #[test]
    fn test_scenario2_memory_degradation_validation() {
        let scenario = MemoryDegradationScenario::new("test-002".to_string());
        let criteria = MemoryDegradationValidator::validate(&scenario);

        assert_eq!(criteria.criteria.len(), 5);
        let report = criteria.get_report();
        assert!(report.contains("Scenario 2: Memory Degradation"));
    }

    #[test]
    fn test_scenario3_io_bottleneck_validation() {
        let scenario = IOBottleneckScenario::new("test-003".to_string());
        let criteria = IOBottleneckValidator::validate(&scenario);

        assert_eq!(criteria.criteria.len(), 5);
        let report = criteria.get_report();
        assert!(report.contains("Scenario 3: I/O Bottleneck"));
    }

    #[test]
    fn test_scenario4_cascading_failures_validation() {
        let scenario = CascadingFailuresScenario::new("test-004".to_string());
        let criteria = CascadingFailuresValidator::validate(&scenario);

        assert_eq!(criteria.criteria.len(), 5);
        let report = criteria.get_report();
        assert!(report.contains("Scenario 4: Cascading Failures"));
    }

    #[test]
    fn test_scenario5_network_partition_validation() {
        let scenario = NetworkPartitionScenario::new("test-005".to_string());
        let criteria = NetworkPartitionValidator::validate(&scenario);

        assert_eq!(criteria.criteria.len(), 5);
        let report = criteria.get_report();
        assert!(report.contains("Scenario 5: Network Partition & Recovery"));
    }

    #[test]
    fn test_validator_engine_all_scenarios() {
        let mut engine = ChaosValidatorEngine::new();

        let s1 = TailLatencyScenario::new("test-001".to_string());
        let s2 = MemoryDegradationScenario::new("test-002".to_string());
        let s3 = IOBottleneckScenario::new("test-003".to_string());
        let s4 = CascadingFailuresScenario::new("test-004".to_string());
        let s5 = NetworkPartitionScenario::new("test-005".to_string());

        engine.validate_all_scenarios(&s1, &s2, &s3, &s4, &s5);

        assert_eq!(engine.total_scenarios, 5);
        assert!(engine.get_overall_pass_rate() >= 0.0);

        let report = engine.generate_validation_report();
        assert!(report.contains("CHAOS ENGINEERING VALIDATION REPORT"));
    }

    #[test]
    fn test_criteria_calculation() {
        let mut criteria = SuccessCriteria::new("test".to_string());
        criteria.add_criterion("criterion1".to_string(), true);
        criteria.add_criterion("criterion2".to_string(), true);
        criteria.add_criterion("criterion3".to_string(), false);

        let passed = criteria.calculate_pass();

        assert!(!passed);  // 2/3 criteria met
        assert_eq!(criteria.completion_percentage, 200.0 / 3.0);  // 66.67%
    }

    #[test]
    fn test_validator_generates_detailed_report() {
        let engine = ChaosValidatorEngine::new();
        let report = engine.generate_validation_report();

        assert!(report.contains("CHAOS ENGINEERING VALIDATION REPORT"));
        assert!(report.contains("Phase I Week 3"));
        assert!(report.contains("Overall Pass Rate"));
    }
}

